scwin.onloadDataSet = function () {
    /* empty */
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/prelistEtc.do",
        ref: "dma_RegisterReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name loadForm
 * @description load Form 처리
 * @param {String} isuexerDd isuexerDd
 * @param {*} isuexerRnd isuexerRnd
 * @param {String} disclsDd disclsDd
 * @param {String} isuTpCd isuTpCd
 * @param {*} ncovexerUsdAmt ncovexerUsdAmt
 * @param {*} exchrt exchrt
 * @param {*} ncovexerAmt ncovexerAmt
 * @param {*} convexerPrc convexerPrc
 * @param {*} convexerUsdAmt convexerUsdAmt
 * @param {*} convexerAmt convexerAmt
 * @param {*} convShrs convShrs
 * @param {String} clmStrtDd clmStrtDd
 * @param {String} clmEndDd clmEndDd
 * @param {String} expDd expDd
 * @param {*} remk remk
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (isuexerDd, isuexerRnd, disclsDd, isuTpCd, ncovexerUsdAmt, exchrt, ncovexerAmt, convexerPrc, convexerUsdAmt, convexerAmt, convShrs, clmStrtDd, clmEndDd, expDd, remk) {
    $c.util.getComponent('dma_RegisterReq').set('isuexerDdCheck', $c.date.dateUnFormat(isuexerDd));
    $c.util.getComponent('dma_RegisterReq').set('isuexerRndCheck', isuexerRnd);
    $c.util.getComponent('cal_isuexerDd').setValue($c.date.dateUnFormat(isuexerDd));
    $c.util.getComponent('ipt_isuexerRnd').setValue(isuexerRnd);
    $c.util.getComponent('cal_disclsDd').setValue($c.date.dateUnFormat(disclsDd));
    (($c.util.getComponent('slc_isuTpCd'))?.setValue?.(isuTpCd));
    $c.util.getComponent('ipt_ncovexerUsdAmt').setValue($c.num.formatNumber(ncovexerUsdAmt));
    $c.util.getComponent('ipt_exchrt').setValue($c.num.formatNumber(exchrt));
    $c.util.getComponent('ipt_ncovexerAmt').setValue($c.num.formatNumber(ncovexerAmt));
    $c.util.getComponent('ipt_convexerPrc').setValue($c.num.formatNumber(convexerPrc));
    $c.util.getComponent('ipt_convexerUsdAmt').setValue($c.num.formatNumber(convexerUsdAmt));
    $c.util.getComponent('ipt_convexerAmt').setValue($c.num.formatNumber(convexerAmt));
    $c.util.getComponent('ipt_convShrs').setValue($c.num.formatNumber(convShrs));
    $c.util.getComponent('cal_clmStrtDd').setValue($c.date.dateUnFormat(clmStrtDd));
    $c.util.getComponent('cal_clmEndDd').setValue($c.date.dateUnFormat(clmEndDd));
    $c.util.getComponent('cal_expDd').setValue($c.date.dateUnFormat(expDd));
    $c.util.getComponent('ipt_remk').setValue(remk);
    scwin.onloadDataSet();
};

/**
 * @method
 * @name calAmt
 * @description cal Amt 처리
 * @returns {void}
 * @hidden N
 */
scwin.calAmt = function () {
    $c.util.getComponent('ipt_ncovexerAmt').setValue($c.num.formatNumber((scwin.rmComma($c.util.getComponent('ipt_ncovexerUsdAmt').getValue()) * scwin.rmComma($c.util.getComponent('ipt_exchrt').getValue()))));
};

/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function () {
    if ($c.util.getComponent('ipt_isuexerRnd').getValue().length <= 0 || $c.util.getComponent('ipt_isuexerRnd').getValue()=== "0") {
        await $c.win.alert("회차를 정확히 입력해주십시요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if ($c.util.getComponent('cal_isuexerDd').getValue().length !== 8) {
        await $c.win.alert("발행일을 정확히 입력해주십시요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if ($c.util.getComponent('cal_disclsDd').getValue().length !== 8) {
        await $c.win.alert("공시일을 정확히 입력해주십시요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if ($c.util.getComponent('cal_clmStrtDd').getValue().length !== 8) {
        await $c.win.alert("전환청구시작일을 정확히 입력해주십시요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if ($c.util.getComponent('cal_clmEndDd').getValue().length !== 8) {
        await $c.win.alert("전환청구종료일을 정확히 입력해주십시요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if ($c.util.getComponent('cal_expDd').getValue().length !== 8) {
        await $c.win.alert("만기일을 정확히 입력해주십시요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if (!await (async () => { const vars = scwin.maxLenCheckVars || []; const names =  scwin.maxLenCheckNames || []; const maxes =  scwin.maxLenCheckMax || []; for (let i = 0; i < vars.length; i++) { const c = $c.util.getComponent(vars[i]); if (!c || !c.getValue) { continue; } const len = $c.str.getByteLength(String(c.getValue() ?? "")); const max = Number(maxes[i]) || 0; if (max && len > max) { await $c.win.alert(String(names[i]) + "의 최대길이(" + max + ")를 \n" + (len - max) + " Byte 만큼 초과하였습니다.\n수정후 저장하세요"); if (c.setFocus) { c.setFocus(); } return false; } } return true; })()) {
        return false;
    }
    return true;
};

