 */
scwin.new789 = async function () {
    if(!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) return ;

